/* Independently AI-illustrated component sprites, inspired by 2024 Big Box physical pieces.
   No original publisher image is embedded. Rule text, values, counts and positions remain code-driven. */
(function(){'use strict';
const assets={"fish":"data:image/webp;base64,","wood":"data:image/webp;base64,","boat":"data:image/webp;base64,","coin":"data:image/webp;base64,","worker":"data:image/webp;base64,","forest":"data:image/webp;base64,","unissued":"data:image/webp;base64,","share":"data:image/webp;base64,","elder":"data:image/webp;base64,","buildingA":"data:image/webp;base64,","buildingB":"data:image/webp;base64,","ship":"data:image/webp;base64,","worker-red":"data:image/webp;base64,","worker-blue":"data:image/webp;base64,","worker-yellow":"data:image/webp;base64,","worker-green":"data:image/webp;base64,","worker-gray":"data:image/webp;base64,"};
const palette={red:'#c44b42',blue:'#437ba8',yellow:'#c7a336',green:'#529361',gray:'#a5a5a0'};
function workerKey(c){let v=(c||'#c44b42').replace('#','');if(!/^[0-9a-f]{6}$/i.test(v))return 'worker-red';let a=[0,2,4].map(i=>parseInt(v.slice(i,i+2),16));let k=Object.entries(palette).map(([k,h])=>[k,[1,3,5].reduce((s,i,j)=>s+(parseInt(h.slice(i,i+2),16)-a[j])**2,0)]).sort((a,b)=>a[1]-b[1])[0][0];return 'worker-'+k;}
function sprite(g,k,x,y,w,h,fit='xMidYMid meet'){if(!assets[k])return false;let im=document.createElementNS('http://www.w3.org/2000/svg','image');for(const [a,b] of Object.entries({href:assets[k],x,y,width:w,height:h,preserveAspectRatio:fit,'data-rm-art':k}))im.setAttribute(a,b);g.append(im);return true;}
function installPractice(){let st=document.createElement('style');let url=k=>`url("${assets[k]}")`;st.textContent=`body:not(.race) .fish{background:transparent ${url('fish')} center/contain no-repeat!important;clip-path:none;width:28px;height:18px}body:not(.race) .wood{background:transparent ${url('wood')} center/contain no-repeat!important;box-shadow:none;border:0;width:23px;height:22px}body:not(.race) .gold{background:transparent ${url('coin')} center/contain no-repeat!important;box-shadow:none;border:0;width:22px;height:22px}body:not(.race) .forest{background:transparent ${url('forest')} center/100% 100% no-repeat!important;border:0;text-shadow:0 1px 3px #173722;width:73px;height:30px}body:not(.race) .share{background:transparent ${url('share')} center/100% 100% no-repeat!important;border:0;min-width:51px;height:31px}body:not(.race) .share.off{background:transparent ${url('unissued')} center/100% 100% no-repeat!important}body:not(.race) .disc[data-rm-disc]{border:0;box-shadow:none;border-radius:0;background-color:transparent!important;background-size:contain!important;background-position:center!important;background-repeat:no-repeat!important}body:not(.race) .ship[data-rm-ship]{background:#f3e4c6 ${url('ship')} center/cover no-repeat;color:#fff;text-shadow:0 1px 4px #172b32,0 0 2px #172b32;min-height:37px;padding:9px 8px}body:not(.race) .ship[data-rm-start]{background:#eee4d0 ${url('boat')} 5px center/30px auto no-repeat;padding-left:40px}`+Object.keys(palette).map(k=>`body:not(.race) .disc[data-rm-disc="${k}"]{background-image:${url('worker-'+k)}!important}`).join('');document.head.append(st);}
window.RMNusArt={assets,palette,workerKey,sprite,installPractice};
})();
